//! 🧪️ The empty persistent builder uses one actual finite Source and resident replies.
use semio_framework_value_control_contract::{OriginalEffectReply,RetainedAllocationEffect,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedWorkOutcome,RetainedWorkPoll,RetirementDemand,ValueError};
use semio_framework_value_persistent::list::persistent::{PersistentList,PersistentListBuilder};
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};

fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn run<E:std::fmt::Debug>(bank:&mut EffectBank,g:RetainedCloneGrant,work:u64,op:impl FnOnce(&mut RetainedAllocationEffect<'_>)->RetainedWorkOutcome<RetainedCloneStep,E>)->RetainedCloneStep{let((poll,marker),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run(g,work,|effect|RetainedWorkPoll::Complete(op(effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("native builder leaf suspended")};let step=turn.result.unwrap();let progress=step.progress();if let Some(bytes)=marker{assert_eq!(bytes,heap.0)}assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));assert_eq!(bank.take_admitted(),if turn.work==0{None}else{Some(true)});bank.post(progress,g,heap);step}

struct CloseProducer{owner:semio_framework_value_retained_clone::RetainedCloneClose,source:semio_framework_value_control_contract::OriginalSourceTurnIdentity}
impl semio_framework_value_control_contract::OriginalEffectProducer for CloseProducer{
 type Output=RetainedCloneStep;type Failure=semio_framework_value_retirement::OriginalRetirementFailure;type Context<'a,'b>=semio_framework_value_control_contract::OriginalSourceTurnIdentity where 'b:'a;
 fn validate_context<'a,'b>(&self,source:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{if *source==self.source{Ok(())}else{Err(ValueError::invariant("persistent builder cleanup Source changed"))}}
 fn source_turn<'a,'b>(&self,source:&Self::Context<'a,'b>)->Option<semio_framework_value_control_contract::OriginalSourceTurnIdentity>where 'b:'a{Some(*source)}
 fn receive<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<semio_framework_value_control_contract::OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.owner.step_into(4096,effect,reply)}
 fn recover<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<semio_framework_value_control_contract::OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.owner.recover_step_into(4096,effect,reply)}
}
fn close_output(bank:&mut EffectBank,output:&mut Option<PersistentList<u64>>){use semio_framework_value_control_contract::OriginalEffectAuthority;let mut close=semio_framework_value_retained_clone::RetainedCloneClose::default();let d=close.next_owner_demands::<PersistentList<u64>>(true,&None,4096).unwrap();let work=close.next_owner_work::<PersistentList<u64>>(true,&None,4096).unwrap();run(bank,grant(d),work,|effect|{let turn=close.begin_granted(output,effect);RetainedWorkOutcome{result:turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default()))),work:turn.work}});assert!(output.is_none());let source=bank.source_witness().identity();let mut authority=Some(OriginalEffectAuthority::new(CloseProducer{owner:close,source}));let mut action=None;let mut answer=None;for _ in 0..10000{if authority.as_ref().unwrap().inspect(|p|p.owner.is_empty()){break}let(d,units)=authority.as_ref().unwrap().inspect(|p|{assert!(!p.owner.requires_original_birth()&&!p.owner.requires_original_control());(p.owner.next_owner_demands::<PersistentList<u64>>(false,&None,4096).unwrap(),p.owner.next_owner_work::<PersistentList<u64>>(false,&None,4096).unwrap())});let g=grant(d);let mut observed=(0,0);let mut spent=0u128;loop{let((poll,marker),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run_with_source(g,units,|effect,witness|{let before=effect.performed_work();let mut context=witness.identity();let ready=authority.as_mut().unwrap().drive(&mut context,effect,&mut action).unwrap();let work=effect.performed_work()-before;if ready{RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work})}else{RetainedWorkPoll::Pending{work}}}));observed.0+=heap.0;observed.1+=heap.1;spent+=poll.work();if let Some(bytes)=marker{assert_eq!(bytes,observed.0)}if let RetainedWorkPoll::Complete(done)=poll{done.result.unwrap();assert!(action.as_mut().unwrap().transfer_reply(&mut answer).unwrap());authority.as_mut().unwrap().finish(&mut action).unwrap();let step=answer.take().unwrap().unwrap();assert_eq!(observed,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert_eq!(bank.take_admitted(),if spent==0{None}else{Some(true)});bank.post(step.progress(),g,observed);break}}}assert!(authority.as_ref().unwrap().inspect(|p|p.owner.is_empty()));let d=OriginalEffectAuthority::<CloseProducer>::producer_transfer_demand().unwrap();let g=grant(d);let mut producer=None;let((poll,marker),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run(g,1,|effect|RetainedWorkPoll::Complete(OriginalEffectAuthority::transfer_producer(&mut authority,&source,&mut producer,effect))));let RetainedWorkPoll::Complete(done)=poll else{panic!("cleanup producer transfer pending")};let progress=done.result.unwrap().unwrap();if let Some(bytes)=marker{assert_eq!(bytes,heap.0)}assert_eq!(heap,(0,0));assert_eq!(bank.take_admitted(),Some(true));bank.post(progress,g,heap);let d=RetirementDemand{copy_bytes:std::mem::size_of::<Option<CloseProducer>>(),depth:1,..Default::default()};let g=grant(d);let((poll,marker),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run(g,1,|effect|{assert!(effect.performed(1).unwrap());drop(producer.take());RetainedWorkPoll::Complete(RetainedWorkOutcome::<_,ValueError>{result:Ok(()),work:1})}));let RetainedWorkPoll::Complete(done)=poll else{panic!("cleanup producer release pending")};done.result.unwrap();assert!(marker.is_none());assert_eq!(heap,(0,0));assert_eq!(bank.take_admitted(),Some(true));bank.post(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()},g,heap);}

struct BuilderCloseProducer<'a>{builder:&'a mut PersistentListBuilder<u64>,source:semio_framework_value_control_contract::OriginalSourceTurnIdentity}
impl semio_framework_value_control_contract::OriginalEffectProducer for BuilderCloseProducer<'_>{type Output=RetainedCloneStep;type Failure=semio_framework_value_retirement::OriginalRetirementFailure;type Context<'a,'b>=semio_framework_value_control_contract::OriginalSourceTurnIdentity where 'b:'a;fn validate_context<'a,'b>(&self,source:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{if *source==self.source{Ok(())}else{Err(ValueError::invariant("builder cleanup Source changed"))}}fn source_turn<'a,'b>(&self,source:&Self::Context<'a,'b>)->Option<semio_framework_value_control_contract::OriginalSourceTurnIdentity>where 'b:'a{Some(*source)}fn receive<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<semio_framework_value_control_contract::OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.builder.close_into(4096,effect,reply)}fn recover<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<semio_framework_value_control_contract::OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.builder.recover_close_into(4096,effect,reply)}}
fn close_builder(bank:&mut EffectBank,builder:&mut PersistentListBuilder<u64>){use semio_framework_value_control_contract::OriginalEffectAuthority;let d=builder.begin_close_demand();run(bank,grant(d),1,|effect|builder.begin_close_paid(effect));let source=bank.source_witness().identity();let mut authority=Some(OriginalEffectAuthority::new(BuilderCloseProducer{builder,source}));let mut action=None;let mut answer=None;for _ in 0..10000{if authority.as_ref().unwrap().inspect(|p|p.builder.terminal_is_empty()){break}let(d,units)=authority.as_ref().unwrap().inspect(|p|{assert!(!p.builder.requires_original_birth()&&!p.builder.requires_original_control());(p.builder.close_demand(4096).unwrap(),p.builder.close_work_demand(4096).unwrap())});let g=grant(d);let mut observed=(0,0);let mut spent=0u128;loop{let((poll,marker),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run_with_source(g,units,|effect,witness|{let before=effect.performed_work();let mut context=witness.identity();let ready=authority.as_mut().unwrap().drive(&mut context,effect,&mut action).unwrap();let work=effect.performed_work()-before;if ready{RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work})}else{RetainedWorkPoll::Pending{work}}}));observed.0+=heap.0;observed.1+=heap.1;spent+=poll.work();if let Some(bytes)=marker{assert_eq!(bytes,observed.0)}if let RetainedWorkPoll::Complete(done)=poll{done.result.unwrap();assert!(action.as_mut().unwrap().transfer_reply(&mut answer).unwrap());authority.as_mut().unwrap().finish(&mut action).unwrap();let step=answer.take().unwrap().unwrap();assert_eq!(observed,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert_eq!(bank.take_admitted(),if spent==0{None}else{Some(true)});bank.post(step.progress(),g,observed);break}}}assert!(authority.as_ref().unwrap().inspect(|p|p.builder.terminal_is_empty()));let d=OriginalEffectAuthority::<BuilderCloseProducer<'_>>::producer_transfer_demand().unwrap();let g=grant(d);let mut producer=None;let((poll,marker),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run(g,1,|effect|RetainedWorkPoll::Complete(OriginalEffectAuthority::transfer_producer(&mut authority,&source,&mut producer,effect))));let RetainedWorkPoll::Complete(done)=poll else{panic!("builder cleanup transfer pending")};let progress=done.result.unwrap().unwrap();if let Some(bytes)=marker{assert_eq!(bytes,heap.0)}assert_eq!(heap,(0,0));assert_eq!(bank.take_admitted(),Some(true));bank.post(progress,g,heap);let d=RetirementDemand{copy_bytes:std::mem::size_of::<Option<BuilderCloseProducer<'_>>>(),depth:1,..Default::default()};let g=grant(d);let((poll,marker),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run(g,1,|effect|{assert!(effect.performed(1).unwrap());drop(producer.take());RetainedWorkPoll::Complete(RetainedWorkOutcome::<_,ValueError>{result:Ok(()),work:1})}));let RetainedWorkPoll::Complete(done)=poll else{panic!("builder cleanup producer release pending")};done.result.unwrap();assert!(marker.is_none());assert_eq!(heap,(0,0));assert_eq!(bank.take_admitted(),Some(true));bank.post(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()},g,heap);}

#[test]fn empty_builder_preserves_denied_input_and_publishes_once(){let law:serde_json::Value=serde_json::from_str(include_str!("../../🧪️tests/🎟️wallet/📐️.json")).unwrap();let p=&law["small"];let stock=RetainedCloneGrant{maximum_items:p["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:p["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:p["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:p["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:p["maximumDepth"].as_u64().unwrap()as usize};let mut bank=EffectBank::new(Wallet::new(stock,p["fuel"].as_u64().unwrap()));let mut builder=PersistentListBuilder::<u64>::new(0);let d=builder.finish_demand().unwrap();let g=grant(d);let denied=RetainedCloneGrant{maximum_copy_bytes:0,..g};let before=bank.wallet().remaining_work();let step=run(&mut bank,denied,1,|effect|{let start=effect.performed_work();let mut slot=None;let token=OriginalEffectReply::borrow(&mut slot).unwrap();let done=builder.finish_into(effect,token).unwrap();drop(done);RetainedWorkOutcome{result:slot.take().unwrap(),work:effect.performed_work()-start}});assert_eq!(step.progress(),RetainedCloneProgress::default());assert!(!builder.finishing());assert_eq!(bank.wallet().remaining_work(),before);
 let step=run(&mut bank,g,1,|effect|{let start=effect.performed_work();let mut slot=None;let token=OriginalEffectReply::borrow(&mut slot).unwrap();drop(builder.finish_into(effect,token).unwrap());RetainedWorkOutcome{result:slot.take().unwrap(),work:effect.performed_work()-start}});assert!(matches!(step,RetainedCloneStep::Complete(_)));let d=builder.demand().unwrap();let work=builder.advance_work_demand().unwrap();let step=run(&mut bank,grant(d),work,|effect|{let start=effect.performed_work();let mut slot=None;let token=OriginalEffectReply::borrow(&mut slot).unwrap();drop(builder.advance_into(effect,token).unwrap());RetainedWorkOutcome{result:slot.take().unwrap(),work:effect.performed_work()-start}});assert!(matches!(step,RetainedCloneStep::Complete(_)));let mut output:Option<PersistentList<u64>>=None;let d=builder.take_demand().unwrap();let step=run(&mut bank,grant(d),1,|effect|{let start=effect.performed_work();let mut slot=None;let token=OriginalEffectReply::borrow(&mut slot).unwrap();drop(builder.take_into(&mut output,effect,token).unwrap());RetainedWorkOutcome{result:slot.take().unwrap(),work:effect.performed_work()-start}});assert!(matches!(step,RetainedCloneStep::Complete(_)));assert!(output.as_ref().unwrap().is_empty());let d=builder.begin_close_demand();let step=run(&mut bank,grant(d),1,|effect|builder.begin_close_paid(effect));assert!(matches!(step,RetainedCloneStep::Progress(_)));assert!(builder.terminal_is_empty());drop(builder);drop(output.take());assert!(bank.is_idle());}

#[test]fn one_leaf_keeps_the_original_row_through_birth_publication_and_paid_close(){use semio_framework_value_shared_issuance::{SealedShared,SharedIssuer};let law:serde_json::Value=serde_json::from_str(include_str!("../../🧪️tests/🎟️wallet/📐️.json")).unwrap();let p=&law["small"];let stock=RetainedCloneGrant{maximum_items:p["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:p["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:p["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:p["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:p["maximumDepth"].as_u64().unwrap()as usize};let mut bank=EffectBank::new(Wallet::new(stock,p["fuel"].as_u64().unwrap()));let mut raw=Some(37u64);let mut row=None;let d=SealedShared::<u64>::source_admission_demand().unwrap();let w=SealedShared::<u64>::source_admission_work_demand();let step=run(&mut bank,grant(d),w,|effect|SealedShared::admit_from(&mut raw,SharedIssuer::owned(),&mut row,effect));assert!(matches!(step,RetainedCloneStep::Complete(_)));assert!(raw.is_none());let address=row.as_ref().unwrap().get()as*const u64;let mut builder=PersistentListBuilder::<u64>::new(1);macro_rules! selected{($d:expr,$work:expr,$action:expr)=>{{let d=$d;run(&mut bank,grant(d),$work,|effect|{let before=effect.performed_work();let mut slot=None;let token=OriginalEffectReply::borrow(&mut slot).unwrap();drop(($action)(effect,token).unwrap());RetainedWorkOutcome{result:slot.take().unwrap(),work:effect.performed_work()-before}})}}}let step=selected!(builder.adopt_demand().unwrap(),1,|effect,token|builder.adopt_into(&mut row,effect,token));assert!(matches!(step,RetainedCloneStep::Complete(_)));assert!(row.is_none());let step=selected!(builder.finish_demand().unwrap(),1,|effect,token|builder.finish_into(effect,token));assert!(matches!(step,RetainedCloneStep::Complete(_)));let mut saw_page=false;for turn in 0..10000{if builder.output_ready(){break}let d=builder.demand().unwrap();let work=builder.advance_work_demand().unwrap();let step=selected!(d,work,|effect,token|builder.advance_into(effect,token));if step.progress().retained_capacity_bytes>0{saw_page=true}assert!(turn<9999)}assert!(saw_page&&builder.output_ready());let mut output=None;let step=selected!(builder.take_demand().unwrap(),1,|effect,token|builder.take_into(&mut output,effect,token));assert!(matches!(step,RetainedCloneStep::Complete(_)));let list=output.as_ref().unwrap();assert_eq!(list.len(),1);assert_eq!(list.get(0).unwrap()as*const u64,address);close_builder(&mut bank,&mut builder);assert!(builder.terminal_is_empty());drop(builder);close_output(&mut bank,&mut output);assert!(output.is_none());assert!(bank.is_idle());}

#[test]fn branch_boundary_retains_each_row_and_releases_the_same_paid_owners(){use semio_framework_value_shared_issuance::{SealedShared,SharedIssuer};let cases:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();assert!(cases["cases"].as_array().unwrap().iter().any(|case|case["length"]==17));let law:serde_json::Value=serde_json::from_str(include_str!("../../🧪️tests/🎟️wallet/📐️.json")).unwrap();let p=&law["small"];let stock=RetainedCloneGrant{maximum_items:p["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:p["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:p["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:p["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:p["maximumDepth"].as_u64().unwrap()as usize};let mut bank=EffectBank::new(Wallet::new(stock,p["fuel"].as_u64().unwrap()));let mut builder=PersistentListBuilder::<u64>::new(17);let mut pointers=Vec::new();macro_rules! selected{($d:expr,$work:expr,$action:expr)=>{{let d=$d;assert!(d.copy_bytes<=4096);run(&mut bank,grant(d),$work,|effect|{let before=effect.performed_work();let mut slot=None;let token=OriginalEffectReply::borrow(&mut slot).unwrap();drop(($action)(effect,token).unwrap());RetainedWorkOutcome{result:slot.take().unwrap(),work:effect.performed_work()-before}})}}}for value in 0..17u64{let mut raw=Some(value);let mut row=None;let d=SealedShared::<u64>::source_admission_demand().unwrap();let work=SealedShared::<u64>::source_admission_work_demand();run(&mut bank,grant(d),work,|effect|SealedShared::admit_from(&mut raw,SharedIssuer::owned(),&mut row,effect));pointers.push(row.as_ref().unwrap().get()as*const u64);let step=selected!(builder.adopt_demand().unwrap(),1,|effect,token|builder.adopt_into(&mut row,effect,token));assert!(matches!(step,RetainedCloneStep::Complete(_)));assert!(row.is_none());for turn in 0..10000{if builder.accepts_row(){break}let d=builder.demand().unwrap();let work=builder.advance_work_demand().unwrap();selected!(d,work,|effect,token|builder.advance_into(effect,token));assert!(turn<9999)}}selected!(builder.finish_demand().unwrap(),1,|effect,token|builder.finish_into(effect,token));for turn in 0..10000{if builder.output_ready(){break}let d=builder.demand().unwrap();let work=builder.advance_work_demand().unwrap();selected!(d,work,|effect,token|builder.advance_into(effect,token));assert!(turn<9999)}let mut output=None;selected!(builder.take_demand().unwrap(),1,|effect,token|builder.take_into(&mut output,effect,token));let list=output.as_ref().unwrap();assert_eq!(list.len(),17);for(index,pointer)in pointers.iter().enumerate(){assert_eq!(list.get(index).unwrap()as*const u64,*pointer);assert_eq!(*list.get(index).unwrap(),index as u64)}close_builder(&mut bank,&mut builder);drop(builder);close_output(&mut bank,&mut output);assert!(bank.is_idle());}

#[test]fn cancellation_keeps_each_staged_page_owner_on_the_original_bank(){use semio_framework_value_shared_issuance::{SealedShared,SharedIssuer};let law:serde_json::Value=serde_json::from_str(include_str!("../../🧪️tests/🎟️wallet/📐️.json")).unwrap();let p=&law["small"];let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for cut in 0..7{assert!(fixture["preparation"]["cuts"].as_array().unwrap().contains(&serde_json::json!(cut)));let stock=RetainedCloneGrant{maximum_items:p["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:p["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:p["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:p["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:p["maximumDepth"].as_u64().unwrap()as usize};let mut bank=EffectBank::new(Wallet::new(stock,p["fuel"].as_u64().unwrap()));let mut raw=Some(37u64);let mut row=None;let d=SealedShared::<u64>::source_admission_demand().unwrap();run(&mut bank,grant(d),SealedShared::<u64>::source_admission_work_demand(),|effect|SealedShared::admit_from(&mut raw,SharedIssuer::owned(),&mut row,effect));let mut builder=PersistentListBuilder::<u64>::new(1);macro_rules! selected{($d:expr,$work:expr,$action:expr)=>{{let d=$d;run(&mut bank,grant(d),$work,|effect|{let before=effect.performed_work();let mut slot=None;let token=OriginalEffectReply::borrow(&mut slot).unwrap();drop(($action)(effect,token).unwrap());RetainedWorkOutcome{result:slot.take().unwrap(),work:effect.performed_work()-before}})}}}selected!(builder.adopt_demand().unwrap(),1,|effect,token|builder.adopt_into(&mut row,effect,token));selected!(builder.finish_demand().unwrap(),1,|effect,token|builder.finish_into(effect,token));for _ in 0..cut{if builder.output_ready(){break}let d=builder.demand().unwrap();let work=builder.advance_work_demand().unwrap();selected!(d,work,|effect,token|builder.advance_into(effect,token));}close_builder(&mut bank,&mut builder);assert!(builder.terminal_is_empty());drop(builder);assert!(bank.is_idle());}}

